<?php
require_once 'auth.php';require_admin();$pdo=db();$kind=$_POST['kind']??'';$tables=['category'=>'categories','collection'=>'collections'];if(!$pdo||!isset($tables[$kind])){header('Location: index.php?error=Yêu cầu không hợp lệ');exit;}$table=$tables[$kind];$list=$kind==='category'?'categories.php':'collections.php';$form=$kind==='category'?'category-form.php':'collection-form.php';$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$code=trim($_POST['code']??'');$image=trim($_POST['image']??'');$coefficient=(float)($_POST['coefficient']??0);$notes=trim($_POST['notes']??'');if($name===''||!preg_match('/^[a-z0-9-]+$/',$code)||$coefficient<0){header('Location: '.$form.'?error='.urlencode('Vui lòng kiểm tra lại thông tin').($id?'&id='.$id:''));exit;}try{if($id){$pdo->prepare("UPDATE $table SET name=?,code=?,image=?,coefficient=?,notes=? WHERE id=?")->execute([$name,$code,$image?:null,$coefficient,$notes?:null,$id]);$msg='Đã lưu thay đổi';}else{$pdo->prepare("INSERT INTO $table(name,code,image,coefficient,notes) VALUES(?,?,?,?,?)")->execute([$name,$code,$image?:null,$coefficient,$notes?:null]);$msg='Đã tạo mục mới';}header('Location: '.$list.'?ok='.urlencode($msg));}catch(Throwable $e){header('Location: '.$form.'?error='.urlencode('Không thể lưu, mã có thể đã tồn tại').($id?'&id='.$id:''));}
